"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["54229"],{44491(e){e.exports=JSON.parse('{"id":"FIN-771","slug":"structural-unemployment","term":"Structural Unemployment","also_known_as":[],"difficulty":"Intermediate","definition":"Structural unemployment is long-term unemployment that occurs when there is a mismatch between the skills or locations of workers and the jobs available in the economy.","explanation":["Structural unemployment arises from deep changes in the economy, such as new technology, shifts in consumer demand, globalisation or the decline of particular industries. Even when the economy is growing and jobs are available, some workers cannot fill them because they lack the necessary skills or live in the wrong places.","For example, when coal mines close in a region, former miners may struggle to find work if the new jobs being created are in software development in distant cities. Unless they retrain or relocate, they may remain unemployed for long periods.","Structural unemployment tends to last longer than other types and does not disappear simply because the economy recovers from a recession.","Addressing it usually requires targeted policies, such as retraining programmes, education reform, support for relocating, and policies to encourage new industries in affected regions. Technology-driven changes, such as automation and artificial intelligence, are frequently discussed as potential sources of future structural unemployment."],"note":"","total":1500,"prev":{"slug":"strike-price","term":"Strike Price"},"next":{"slug":"structured-product","term":"Structured Product"}}')}}]);